def profiles() -> tuple[Profile, ...]:
    result: list[Profile] = []
    for row in _ROWS:
        pairs = [tuple(value.split("|")) for value in row[3:]]
        if len(row) != 10 or any(len(pair) != 2 for pair in pairs):
            raise ValueError("Each authored profile needs seven bilingual fields")
        fields = [(p[0], p[1]) for p in pairs]
        result.append(Profile(row[0], row[1], row[2], fields[0], fields[1], fields[2],
                              fields[3], fields[4], fields[5], fields[6]))
    return tuple(result)
